#include <list>
#include <algorithm>

// Demonstrates moving all elements from list1 to list2
void transfer_all(std::list<int>& dest, std::list<int>& src) {
    auto pos = dest.begin();
    // list2.splice(position, source_list)
    // Complexity: O(1)
    dest.splice(pos, src);
    // src is now empty, dest contains all original elements
    // Iterators pointing to elements in src are now valid in dest
}
